To address the "unexpected error" and fully implement the requested features (Alarm Popup, Dual-Engine Seamless Switching, Keyboard Shortcuts, Sleep Timer), I will update the following files:

1.  **`components/VideoPlayer.tsx`**: Completely refactored to support two video elements (A/B switching) for gapless channel changing. Added keyboard controls, sleep timer, and the "Beep" sound logic using Web Audio API.
2.  **`App.tsx`**: Updated to integrate the `AlarmModal` (replacing the native `alert`), manage the `activeReminder` state, and pass `settings` to the video player.
3.  **`components/AlarmModal.tsx`**: Ensured the popup component is correctly implemented (based on previous context).

# Updated files:

## components/VideoPlayer.tsx

```tsx
import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { 
    AlertCircle, Play, RefreshCw, Radio, Music, Square, Star, 
    Captions, StopCircle, Volume2, VolumeX, Maximize, AlarmClock, 
    Check, Clock, Moon, Minimize, Pip, Monitor
} from 'lucide-react';
import { AppTheme, Channel, Country, AppSettings } from '../types';
import { getTimezone } from '../services/iptvService';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  autoPlay?: boolean;
  isRadio?: boolean;
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAddReminder: (channel: Channel, time: string) => void;
  onAddToHistory?: (channel: Channel) => void;
  settings?: AppSettings;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, 
    country,
    autoPlay = true, 
    isRadio = false, 
    theme,
    isFavorite,
    onToggleFavorite,
    onAddReminder,
    onAddToHistory,
    settings = { enableSound: true }
}) => {
  const { styles } = theme;

  // Dual Video Engine State
  const [activePlayerIndex, setActivePlayerIndex] = useState(0); // 0 or 1
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);
  const containerRef = useRef<HTMLDivElement>(null);

  // Audio Context for Beep
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Playback State
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);

  // Features State
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const [signalStrength, setSignalStrength] = useState<number>(0); 
  const [showTranslate, setShowTranslate] = useState(false);
  const [currentTimeStr, setCurrentTimeStr] = useState('');

  // Tools
  const [showAlarmPicker, setShowAlarmPicker] = useState(false);
  const [alarmTime, setAlarmTime] = useState('');
  const [sleepTimer, setSleepTimer] = useState<number | null>(null); // minutes
  const [showSleepMenu, setShowSleepMenu] = useState(false);
  const sleepIntervalRef = useRef<number | null>(null);
  const [aspectRatio, setAspectRatio] = useState<'cover' | 'contain' | '16/9' | '4/3'>('contain');

  // Radio Visualizer
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>();
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  // --- Helpers ---

  const playBeep = useCallback(() => {
    if (!settings.enableSound) return;
    try {
        if (!audioCtxRef.current) {
            audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
        const ctx = audioCtxRef.current;
        if (ctx.state === 'suspended') ctx.resume();

        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(880, ctx.currentTime); // A5
        osc.frequency.exponentialRampToValueAtTime(440, ctx.currentTime + 0.1); // Drop pitch

        gain.gain.setValueAtTime(0.1, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.start();
        osc.stop(ctx.currentTime + 0.15);
    } catch (e) {
        console.error("Audio beep failed", e);
    }
  }, [settings.enableSound]);

  // --- Clock ---
  useEffect(() => {
    if (!country && !channel) return;
    const tz = country ? getTimezone(country.code) : 'UTC';

    const updateTime = () => {
        try {
            const now = new Date();
            const timeString = new Intl.DateTimeFormat('en-US', {
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false,
                timeZone: tz
            }).format(now);
            setCurrentTimeStr(timeString);
        } catch (e) {
            setCurrentTimeStr(new Date().toLocaleTimeString('en-GB'));
        }
    };

    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, [country, channel]);

  // --- Sleep Timer ---
  useEffect(() => {
      if (sleepTimer !== null) {
          sleepIntervalRef.current = window.setInterval(() => {
              setSleepTimer(prev => {
                  if (prev === null || prev <= 1) {
                      // Time's up
                      if (videoRefs[0].current) videoRefs[0].current.pause();
                      if (videoRefs[1].current) videoRefs[1].current.pause();
                      setIsPlaying(false);
                      return null;
                  }
                  return prev - 1;
              });
          }, 60000); // 1 min
      }
      return () => {
          if (sleepIntervalRef.current) clearInterval(sleepIntervalRef.current);
      };
  }, [sleepTimer]);

  // --- Keyboard Shortcuts ---
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

          switch(e.code) {
              case 'Space':
                  e.preventDefault();
                  togglePlay();
                  break;
              case 'KeyM':
                  setIsMuted(prev => !prev);
                  break;
              case 'KeyF':
                  toggleFullscreen();
                  break;
              case 'ArrowUp':
                  e.preventDefault();
                  setVolume(v => Math.min(1, v + 0.1));
                  break;
              case 'ArrowDown':
                  e.preventDefault();
                  setVolume(v => Math.max(0, v - 0.1));
                  break;
          }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPlaying]); // Re-bind if needed, or use functional updates

  // --- Volume Sync ---
  useEffect(() => {
      videoRefs.forEach(ref => {
          if (ref.current) {
              ref.current.volume = volume;
              ref.current.muted = isMuted;
          }
      });
  }, [volume, isMuted]);


  // --- DUAL ENGINE LOADING LOGIC ---
  useEffect(() => {
      const targetUrl = channel?.url;
      if (!targetUrl) return;

      if (onAddToHistory && channel) {
          onAddToHistory(channel);
      }

      // Determine which player is currently background
      const nextIndex = activePlayerIndex === 0 ? 1 : 0;
      const nextVideo = videoRefs[nextIndex].current;
      const currentVideo = videoRefs[activePlayerIndex].current;

      if (!nextVideo) return;

      setLoading(true);
      setError(null);
      setSignalStrength(1);

      // Clean up previous HLS on the target player
      if (hlsRefs.current[nextIndex]) {
          hlsRefs.current[nextIndex]?.destroy();
          hlsRefs.current[nextIndex] = null;
      }

      const onReadyToPlay = () => {
          // Crossfade logic
          setActivePlayerIndex(nextIndex);
          setLoading(false);
          setError(null);
          setIsPlaying(true);
          setSignalStrength(4);
          playBeep();

          // Stop the *previous* video to save resources
          if (currentVideo) {
              currentVideo.pause();
              currentVideo.src = "";
              if (hlsRefs.current[activePlayerIndex]) {
                  hlsRefs.current[activePlayerIndex]?.destroy();
                  hlsRefs.current[activePlayerIndex] = null;
              }
          }

          // Setup Visualizer if Radio
          if (isRadio) setupVisualizer(nextVideo);
      };

      const onError = (e: any) => {
          console.error("Load error on engine", nextIndex, e);
          // Only show error if we are trying to switch to this one
          // If the old one is still playing, maybe just keep playing it?
          // For now, we force switch to show error
          setActivePlayerIndex(nextIndex);
          setError("无法播放此源");
          setLoading(false);
          setSignalStrength(0);
      };

      // Initialize Load
      if (targetUrl.includes('.m3u8') && Hls.isSupported()) {
          const hls = new Hls({
              enableWorker: true,
              lowLatencyMode: true,
              backBufferLength: 90
          });
          hlsRefs.current[nextIndex] = hls;
          hls.loadSource(targetUrl);
          hls.attachMedia(nextVideo);

          hls.on(Hls.Events.MANIFEST_PARSED, () => {
              if (autoPlay) nextVideo.play().catch(() => {});
          });
          hls.on(Hls.Events.ERROR, (event, data) => {
              if (data.fatal) {
                   switch (data.type) {
                        case Hls.ErrorTypes.NETWORK_ERROR:
                            hls.startLoad();
                            break;
                        case Hls.ErrorTypes.MEDIA_ERROR:
                            hls.recoverMediaError();
                            break;
                        default:
                            onError(data);
                            hls.destroy();
                            break;
                   }
              }
          });
      } else {
          nextVideo.src = targetUrl;
          nextVideo.load();
          if (autoPlay) nextVideo.play().catch(() => {});
      }

      // Event listeners for seamless switch
      const handleCanPlay = () => {
          // Wait a tiny bit to ensure frames are ready
          onReadyToPlay();
      };

      // Reset listeners
      nextVideo.oncanplay = handleCanPlay;
      nextVideo.onerror = onError;
      nextVideo.onwaiting = () => setSignalStrength(2);

  }, [channel?.url]); // Only re-run if URL changes

  // --- Visualizer ---
  const setupVisualizer = (video: HTMLVideoElement) => {
      if (!canvasRef.current) return;

      try {
          if (!audioCtxRef.current) {
              audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
          }
          const ctx = audioCtxRef.current!;

          if (!analyserRef.current) {
              analyserRef.current = ctx.createAnalyser();
              analyserRef.current.fftSize = 256;
          }

          // Re-connect source if needed (tricky with CORS, often fails on cross-origin video)
          // For this demo, we might simulate if CORS fails, or try-catch
          // Note: createMediaElementSource requires CORS setup on server side usually
      } catch (e) {
          // Fallback to CSS animation if Web Audio fails
      }

      const draw = () => {
         if (!canvasRef.current || !isPlaying) return;
         const cvs = canvasRef.current;
         const ctx = cvs.getContext('2d');
         if (!ctx) return;

         // Simulated data if analyser fails due to CORS
         const w = cvs.width;
         const h = cvs.height;
         ctx.clearRect(0, 0, w, h);

         const barWidth = (w / 20);
         let x = 0;

         for (let i = 0; i < 20; i++) {
             const height = Math.random() * h * 0.8;
             ctx.fillStyle = theme.styles.accentColor;
             // Add glow
             ctx.shadowBlur = 10;
             ctx.shadowColor = theme.styles.accentColor;

             ctx.fillRect(x, h - height, barWidth - 2, height);
             x += barWidth;
         }

         animationFrameRef.current = requestAnimationFrame(draw);
      };
      draw();
  };

  useEffect(() => {
      return () => {
          if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
      };
  }, []);

  // --- Handlers ---

  const togglePlay = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;
    if (isPlaying) {
      video.pause();
      setIsPlaying(false);
    } else {
      video.play();
      setIsPlaying(true);
    }
  };

  const toggleFullscreen = () => {
      if (!document.fullscreenElement) {
          containerRef.current?.requestFullscreen();
      } else {
          document.exitFullscreen();
      }
  };

  const togglePiP = async () => {
      const video = videoRefs[activePlayerIndex].current;
      if (!video) return;
      try {
          if (document.pictureInPictureElement) {
              await document.exitPictureInPicture();
          } else {
              await video.requestPictureInPicture();
          }
      } catch (e) {
          console.error(e);
      }
  };

  const handleStartRecording = () => {
      const video = videoRefs[activePlayerIndex].current;
      if (!video) return;
      try {
          // @ts-ignore
          const stream = video.captureStream ? video.captureStream() : video.mozCaptureStream ? video.mozCaptureStream() : null;
          if (!stream) { alert("浏览器不支持录制"); return; }

          const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
          mediaRecorderRef.current = mediaRecorder;
          chunksRef.current = [];

          mediaRecorder.ondataavailable = (e) => {
              if (e.data.size > 0) chunksRef.current.push(e.data);
          };

          mediaRecorder.onstop = () => {
              const blob = new Blob(chunksRef.current, { type: 'video/webm' });
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `recording-${Date.now()}.webm`;
              a.click();
              window.URL.revokeObjectURL(url);
              setIsRecording(false);
          };

          mediaRecorder.start();
          setIsRecording(true);
      } catch (e) {
          alert("无法录制 (CORS 限制)");
      }
  };

  if (!channel) {
    return (
      <div className={`w-full aspect-video flex flex-col items-center justify-center ${styles.card} ${styles.layoutShape} border-dashed opacity-70`}>
        {isRadio ? <Radio className={`w-16 h-16 mb-4 ${styles.textDim}`} /> : <Monitor className={`w-16 h-16 mb-4 ${styles.textDim}`} />}
        <p className={styles.textDim}>请选择{isRadio ? '电台' : '频道'}</p>
      </div>
    );
  }

  // Calculate Aspect Ratio Class
  const getAspectRatioClass = () => {
      switch(aspectRatio) {
          case 'cover': return 'object-cover';
          case 'contain': return 'object-contain';
          case '16/9': return 'object-fill aspect-video';
          case '4/3': return 'object-fill aspect-[4/3]';
          default: return 'object-contain';
      }
  };

  return (
    <div className="w-full space-y-4" ref={containerRef}>
      <div className={`
        relative w-full aspect-video ${styles.layoutShape} overflow-hidden shadow-2xl group 
        ${styles.border} ${theme.type === 'web95' ? 'bg-black' : styles.bgSidebar}
      `}>

        {theme.type === 'web95' && (
             <div className="absolute top-0 left-0 right-0 h-8 bg-[#000080] flex items-center justify-between px-2 z-20 select-none">
                 <span className="text-white font-bold text-xs">Media Player - {channel.name}</span>
                 <div className="flex gap-1">
                     <div className="w-3 h-3 bg-gray-300"></div><div className="w-3 h-3 bg-gray-300"></div>
                 </div>
             </div>
        )}

        {/* Video Engines */}
        {[0, 1].map((idx) => (
            <video
                key={idx}
                ref={videoRefs[idx]}
                className={`absolute inset-0 w-full h-full transition-opacity duration-700 ease-in-out ${getAspectRatioClass()}`}
                style={{ 
                    opacity: activePlayerIndex === idx ? 1 : 0,
                    paddingTop: theme.type === 'web95' ? '32px' : '0'
                }}
                playsInline
                crossOrigin="anonymous"
            />
        ))}

        {/* Radio Visuals */}
        {isRadio && (
            <div className={`absolute inset-0 flex items-center justify-center pointer-events-none ${styles.bgSidebar} z-0`}>
                <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-30" width={600} height={400} />
                <div className={`relative z-10 w-32 h-32 rounded-full ${styles.card} flex items-center justify-center animate-pulse`}>
                    {channel.logo ? (
                        <img src={channel.logo} className="w-24 h-24 rounded-full object-cover" />
                    ) : (
                        <Music className={`w-12 h-12 ${styles.textMain}`} />
                    )}
                </div>
            </div>
        )}

        {/* Loading Overlay */}
        {loading && (
             <div className={`absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/50 backdrop-blur-sm transition-opacity`}>
                <div className={`p-4 rounded-full ${styles.card} animate-spin`}>
                    <RefreshCw className={`w-8 h-8 ${styles.textMain}`} />
                </div>
                <span className={`mt-4 font-mono text-xs ${styles.textMain}`}>BUFFERING STREAM...</span>
             </div>
        )}

        {/* Translate Overlay */}
        {showTranslate && (
            <div className="absolute bottom-24 left-0 right-0 px-8 text-center z-20 pointer-events-none">
                <div className={`bg-black/80 text-white px-6 py-3 rounded-xl inline-block backdrop-blur-md border border-white/10`}>
                    <p className="text-lg font-medium">
                        <span className="animate-pulse">●</span> 正在实时翻译音频...
                    </p>
                </div>
            </div>
        )}

        {/* Error Overlay */}
        {error && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/90">
            <AlertCircle className="w-12 h-12 text-red-500 mb-3" />
            <p className="text-white font-medium">{error}</p>
            <button 
              onClick={() => {
                  setLoading(true);
                  setError(null);
                  if(hlsRefs.current[activePlayerIndex]) hlsRefs.current[activePlayerIndex]?.startLoad();
                  else videoRefs[activePlayerIndex].current?.load();
              }}
              className={`mt-4 px-4 py-2 ${styles.buttonPrimary} rounded flex items-center gap-2`}
            >
              <RefreshCw className="w-4 h-4" /> 重试
            </button>
          </div>
        )}

        {/* Controls Overlay */}
        <div className={`
             absolute inset-0 z-20 flex flex-col justify-between p-4 transition-opacity duration-300
             ${theme.type === 'web95' ? 'opacity-100 pointer-events-none' : 'opacity-0 group-hover:opacity-100 bg-gradient-to-t from-black/90 via-transparent to-black/50'}
        `}>
            {/* Top Info */}
            <div className={`flex justify-between items-start pointer-events-auto ${theme.type === 'web95' ? 'mt-8' : ''}`}>
                 <div className="flex gap-2">
                     <div className="bg-red-600 px-2 py-0.5 rounded text-[10px] font-bold text-white border border-white/10 animate-pulse flex items-center">
                        LIVE
                     </div>
                     {sleepTimer !== null && (
                         <div className="bg-blue-600 px-2 py-0.5 rounded text-[10px] font-bold text-white border border-white/10 flex items-center gap-1">
                            <Moon className="w-3 h-3" /> {sleepTimer}m
                         </div>
                     )}
                 </div>

                 {isRecording && (
                    <div className="flex items-center gap-2 bg-red-500/20 border border-red-500/50 px-3 py-1 rounded-full animate-pulse">
                        <div className="w-2 h-2 rounded-full bg-red-500"></div>
                        <span className="text-xs font-bold text-red-400">REC</span>
                    </div>
                 )}
            </div>

            {/* Bottom Controls Bar */}
            <div className={`flex items-center gap-3 pointer-events-auto ${theme.type === 'web95' ? 'bg-[#c0c0c0] p-1 border-2 border-t-white border-l-white border-r-black border-b-black' : ''}`}>

                {/* Play/Pause */}
                <button 
                    onClick={togglePlay}
                    className={`w-9 h-9 ${styles.layoutShape} flex items-center justify-center transition-all ${styles.buttonPrimary}`}
                >
                    {isPlaying ? <Square className="w-4 h-4 fill-current" /> : <Play className="w-4 h-4 fill-current" />}
                </button>

                {/* Volume */}
                <div 
                    className="flex items-center gap-2 group/vol relative"
                    onMouseEnter={() => setShowVolumeSlider(true)}
                    onMouseLeave={() => setShowVolumeSlider(false)}
                >
                    <button 
                        onClick={() => setIsMuted(!isMuted)}
                        className={`w-8 h-8 ${styles.layoutShape} flex items-center justify-center ${styles.button}`}
                    >
                        {isMuted || volume === 0 ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
                    </button>
                    <div className={`overflow-hidden transition-all duration-300 ${showVolumeSlider ? 'w-20 opacity-100' : 'w-0 opacity-0'}`}>
                        <input
                            type="range" min="0" max="1" step="0.05"
                            value={isMuted ? 0 : volume}
                            onChange={(e) => { setVolume(parseFloat(e.target.value)); setIsMuted(false); }}
                            className="w-20 h-1 cursor-pointer accent-current"
                        />
                    </div>
                </div>

                <div className="flex-1"></div>

                {/* Right Side Tools */}
                <div className="flex items-center gap-1.5 relative">

                    {/* Sleep Timer */}
                    <div className="relative">
                        <button
                            onClick={() => setShowSleepMenu(!showSleepMenu)}
                            className={`p-2 ${styles.layoutShape} ${styles.button} ${sleepTimer ? styles.buttonActive : ''}`}
                            title="睡眠定时"
                        >
                            <Moon className="w-4 h-4" />
                        </button>
                        {showSleepMenu && (
                            <div className={`absolute bottom-full mb-2 right-0 ${styles.card} p-1 ${styles.layoutShape} grid gap-1 w-24 text-xs font-bold shadow-xl z-50`}>
                                {[15, 30, 60].map(m => (
                                    <button key={m} onClick={() => { setSleepTimer(m); setShowSleepMenu(false); }} className={`p-2 hover:bg-white/10 text-left ${styles.layoutShape}`}>
                                        {m} 分钟
                                    </button>
                                ))}
                                <button onClick={() => { setSleepTimer(null); setShowSleepMenu(false); }} className="p-2 text-red-400 hover:bg-white/10 text-left">关闭</button>
                            </div>
                        )}
                    </div>

                    {/* Aspect Ratio */}
                    <button
                        onClick={() => setAspectRatio(prev => prev === 'contain' ? 'cover' : prev === 'cover' ? '16/9' : prev === '16/9' ? '4/3' : 'contain')}
                        className={`p-2 ${styles.layoutShape} ${styles.button} text-[10px] font-mono w-8 h-8 flex items-center justify-center`}
                        title="画面比例"
                    >
                        {aspectRatio === 'contain' ? 'FIT' : aspectRatio === 'cover' ? 'FILL' : aspectRatio}
                    </button>

                    {/* Alarm */}
                    <div className="relative">
                        <button
                            onClick={() => setShowAlarmPicker(!showAlarmPicker)}
                            className={`p-2 ${styles.layoutShape} ${showAlarmPicker ? styles.buttonActive : styles.button}`}
                        >
                            <AlarmClock className="w-4 h-4" />
                        </button>
                        {showAlarmPicker && (
                            <div className={`absolute bottom-full mb-3 right-0 ${styles.card} p-3 ${styles.layoutShape} shadow-xl w-56 z-50`}>
                                <h4 className={`text-xs font-bold ${styles.textMain} mb-2`}>添加提醒</h4>
                                <div className="flex gap-2">
                                    <input 
                                        type="time" 
                                        className={`flex-1 px-2 py-1 text-sm focus:outline-none ${styles.input} ${styles.layoutShape}`}
                                        value={alarmTime}
                                        onChange={(e) => setAlarmTime(e.target.value)}
                                    />
                                    <button 
                                        onClick={() => { onAddReminder(channel, alarmTime); setShowAlarmPicker(false); setAlarmTime(''); }}
                                        className={`${styles.buttonPrimary} p-1 rounded hover:opacity-90`}
                                        disabled={!alarmTime}
                                    >
                                        <Check className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Translate */}
                    <button
                        onClick={() => setShowTranslate(!showTranslate)}
                        className={`p-2 ${styles.layoutShape} ${showTranslate ? styles.buttonActive : styles.button}`}
                    >
                        <Captions className="w-4 h-4" />
                    </button>

                    {/* PiP */}
                    <button onClick={togglePiP} className={`p-2 ${styles.layoutShape} ${styles.button}`}>
                        <Pip className="w-4 h-4" />
                    </button>

                    {/* Fullscreen */}
                    <button onClick={toggleFullscreen} className={`p-2 ${styles.layoutShape} ${styles.button}`}>
                        <Maximize className="w-4 h-4" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      {/* Info Bar */}
      <div className="flex items-start justify-between px-2">
