// Special country entry for custom playlists
const CUSTOM_COUNTRY: Country = {
    name: '导入频道 (Custom)',
    code: 'CUSTOM',
    languages: [],
    flag: '📂'
};

const App: React.FC = () => {
  const [countries, setCountries] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<Channel | null>(null);
  const [customChannels, setCustomChannels] = useState<Channel[]>([]);

  const [loadingCountries, setLoadingCountries] = useState(true);
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mode, setMode] = useState<'tv' | 'radio'>('tv');
  const [showSchedule, setShowSchedule] = useState(false);
  const [activeReminder, setActiveReminder] = useState<Reminder | null>(null);
  const [settings, setSettings] = useState<AppSettings>({ enableSound: true });

  const [favorites, setFavorites] = useState<Channel[]>(() => {
      try {
          const saved = localStorage.getItem('global_favorites');
          return saved ? JSON.parse(saved) : [];
      } catch (e) {
          return [];
      }
  });

  const [reminders, setReminders] = useState<Reminder[]>(() => {
    try {
        const saved = localStorage.getItem('global_reminders');
        return saved ? JSON.parse(saved) : [];
    } catch (e) {
        return [];
    }
  });

  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);

  useEffect(() => {
      localStorage.setItem('global_favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
      localStorage.setItem('global_reminders', JSON.stringify(reminders));
  }, [reminders]);

  useEffect(() => {
    const interval = setInterval(() => {
        const now = new Date();
        const currentHours = now.getHours().toString().padStart(2, '0');
        const currentMinutes = now.getMinutes().toString().padStart(2, '0');
        const currentTimeStr = `${currentHours}:${currentMinutes}`;

        reminders.forEach(reminder => {
            if (reminder.timeStr === currentTimeStr) {
                 const lastAlerted = sessionStorage.getItem(`alerted_${reminder.id}_${currentTimeStr}`);
                 if (!lastAlerted) {
                     setActiveReminder(reminder);
                     sessionStorage.setItem(`alerted_${reminder.id}_${currentTimeStr}`, 'true');
                 }
            }
        });
    }, 10000); 

    return () => clearInterval(interval);
  }, [reminders]);

  useEffect(() => {
    const loadCountries = async () => {
      try {
        const data = await fetchCountries();
        setCountries(data);
        const defaultCountry = data.find(c => c.code === 'US') || data[0];
        if (defaultCountry) {
            setSelectedCountry(defaultCountry);
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoadingCountries(false);
      }
    };
    loadCountries();
  }, []);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;

    // Handle Custom Playlist
    if (selectedCountry.code === 'CUSTOM') {
        setChannels(customChannels);
        setLoadingChannels(false);
        return;
    }

    setLoadingChannels(true);
    if (!refresh) {
        setChannels([]);
        setCurrentChannel(null); 
    }

    try {
        let data: Channel[] = [];
        if (mode === 'tv') {
            data = await fetchChannelsByCountry(selectedCountry.code, refresh);
        } else {
            data = await fetchRadioStations(selectedCountry.code, refresh);
        }
        setChannels(data);
    } catch (err) {
        console.error(err);
    } finally {
        setLoadingChannels(false);
    }
  };

  useEffect(() => {
    loadContent();
  }, [selectedCountry, mode]);

  const handleCountrySelect = (country: Country) => {
    setSelectedCountry(country);
    setSidebarOpen(false);
  };

  const handleModeChange = (newMode: 'tv' | 'radio') => {
      if (mode === newMode) return;
      setMode(newMode);
      setSidebarOpen(false);
  };

  const handleChannelSelect = (channel: Channel) => {
      setCurrentChannel(channel);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const toggleFavorite = (channel: Channel) => {
      setFavorites(prev => {
          const exists = prev.some(c => c.id === channel.id);
          if (exists) {
              return prev.filter(c => c.id !== channel.id);
          } else {
              const channelWithMeta = { 
                  ...channel, 
                  type: channel.type || mode 
              };
              return [...prev, channelWithMeta];
          }
      });
  };

  const isFavorite = (channel: Channel | null) => {
      if (!channel) return false;
      return favorites.some(c => c.id === channel.id);
  };

  const handleAddReminder = (channel: Channel, time: string) => {
    const newReminder: Reminder = {
        id: Math.random().toString(36).substr(2, 9),
        channelId: channel.id,
        channelName: channel.name,
        timeStr: time,
        created: Date.now()
    };
    setReminders(prev => [...prev, newReminder]);
    alert(`已设置提醒: ${channel.name} @ ${time}`);
  };

  const handleDeleteReminder = (id: string) => {
    setReminders(prev => prev.filter(r => r.id !== id));
  };

  const handlePlayFromSchedule = (channelId: string) => {
      let channel = channels.find(c => c.id === channelId);
      if (!channel) channel = favorites.find(c => c.id === channelId);

      if (channel) {
          setCurrentChannel(channel);
          setActiveReminder(null);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
          alert("无法在当前列表中找到该频道，请先切换到对应的国家或模式。");
      }
  };

  const handleImportM3U = (content: string) => {
      try {
          const parsed = parseM3U(content);
          const tagged = parsed.map(c => ({...c, type: 'tv' as const}));
          setCustomChannels(tagged);

          if (!countries.find(c => c.code === 'CUSTOM')) {
              setCountries(prev => [CUSTOM_COUNTRY, ...prev]);
          }

          setSelectedCountry(CUSTOM_COUNTRY);
          alert(`成功导入 ${tagged.length} 个频道`);
      } catch (e) {
          alert("解析文件失败，请确认格式正确。");
      }
  };

  return (
    <div className={`flex h-screen ${currentTheme.styles.bgMain} ${currentTheme.styles.font} overflow-hidden transition-colors duration-500`}>
      <Sidebar 
        countries={countries}
        selectedCountry={selectedCountry}
        onSelectCountry={handleCountrySelect}
        isOpen={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        mode={mode}
        onModeChange={handleModeChange}
        themes={THEMES}
        currentTheme={currentTheme}
        onThemeChange={setCurrentTheme}
        favorites={favorites}
        onSelectFavorite={handleChannelSelect}
        onImportM3U={handleImportM3U}
        settings={settings}
        onToggleSound={() => setSettings(prev => ({ ...prev, enableSound: !prev.enableSound }))}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className={`md:hidden ${currentTheme.styles.bgSidebar} border-b ${currentTheme.styles.border} p-4 flex items-center justify-between shrink-0 z-30`}>
            <button onClick={() => setSidebarOpen(true)} className={currentTheme.styles.textMain}>
                <Menu className="w-6 h-6" />
            </button>
            <h1 className={`text-lg font-bold ${currentTheme.styles.textMain}`}>全球实时看和听</h1>
            <div className="flex items-center gap-2">
                <button onClick={() => setShowSchedule(true)} className={currentTheme.styles.textMain}>
                    <CalendarClock className="w-5 h-5" />
                </button>
                <button onClick={() => loadContent(true)} className={currentTheme.styles.textMain}>
                    <RefreshCw className={`w-5 h-5 ${loadingChannels ? 'animate-spin' : ''}`} />
                </button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'} p-4 md:p-6 lg:p-8`}>
            <div className="max-w-7xl mx-auto space-y-8">

                <div className="flex items-center justify-between">
                    <div>
                        <h2 className={`text-2xl md:text-3xl font-bold ${currentTheme.styles.textMain} flex items-center gap-3`}>
                            {selectedCountry ? (
                                <>
                                    <span className="text-4xl">{selectedCountry.flag}</span>
                                    <span>{selectedCountry.name}</span>
                                </>
                            ) : '请选择国家'}
                        </h2>
                        <p className={`mt-1 font-medium ${currentTheme.styles.textDim}`}>
                            {channels.length > 0 
                                ? `找到 ${channels.length} 个${mode === 'tv' ? '直播频道' : '广播电台'}` 
                                : loadingChannels ? '加载中...' : `选择一个${mode === 'tv' ? '国家' : '地区'}开始探索`}
                        </p>
                    </div>

                    <div className="hidden md:flex items-center gap-3">
                        <button 
                            onClick={() => setShowSchedule(true)}
                            className={`flex items-center gap-2 px-3 py-1.5 ${currentTheme.styles.layoutShape} ${currentTheme.styles.button} ${currentTheme.styles.border} transition-all`}
                        >
                            <CalendarClock className="w-4 h-4" />
                            <span>节目单</span>
                        </button>
                        <button 
                            onClick={() => loadContent(true)}
                            className={`flex items-center gap-2 px-3 py-1.5 ${currentTheme.styles.layoutShape} ${currentTheme.styles.button} ${currentTheme.styles.border} transition-all`}
                        >
                            <RefreshCw className={`w-4 h-4 ${loadingChannels ? 'animate-spin' : ''}`} />
                            <span>刷新列表</span>
                        </button>
                    </div>
                </div>

                <VideoPlayer 
                    channel={currentChannel}
                    country={selectedCountry}
                    autoPlay={true}
                    isRadio={mode === 'radio'}
                    theme={currentTheme}
                    isFavorite={isFavorite(currentChannel)}
                    onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)}
                    onAddReminder={handleAddReminder}
                    settings={settings}
                />

                <ChannelGrid 
                    channels={channels}
                    currentChannel={currentChannel}
                    onSelectChannel={handleChannelSelect}
                    loading={loadingChannels}
                    mode={mode}
                    theme={currentTheme}
                    favorites={favorites}
                    onToggleFavorite={toggleFavorite}
                />
            </div>
        </div>
      </main>

      {/* Schedule Modal */}
      <ScheduleList 
        reminders={reminders}
        isOpen={showSchedule}
        onClose={() => setShowSchedule(false)}
        onDelete={handleDeleteReminder}
        theme={currentTheme}
        onPlayChannel={handlePlayFromSchedule}
        allChannels={[...channels, ...favorites]}
      />

      {/* Alarm Popup Modal */}
      <AlarmModal 
         reminder={activeReminder}
         onClose={() => setActiveReminder(null)}
         onWatch={handlePlayFromSchedule}
         theme={currentTheme}
      />

      {/* AI Pet Widget */}
      <AiChatPet theme={currentTheme} />
    </div>
  );
};

export default App;
```

为了满足您的需求，将“收藏栏”移动到“风格切换栏”的正下方，我将对侧边栏（Sidebar）进行布局调整。

为了保持界面整洁并防止收藏频道过多占用太多固定空间，我将把收藏栏设计为一个**可折叠的菜单**（类似设置和风格切换），并限制其最大高度。

以下是修改后的 `components/Sidebar.tsx`：

# Updated files:

## components/Sidebar.tsx

1.  新增 `showFavorites` 状态用于控制折叠。
2.  将收藏夹（Favorites）渲染逻辑从底部的滚动列表移至顶部的固定功能区。
3.  放置顺序调整为：... -> 风格切换 -> **收藏夹** -> 导入按钮。
4.  为收藏夹增加了最大高度 (`max-h-48`) 和独立滚动条，防止频道太多撑爆侧边栏。

```tsx
import React, { useState, useMemo, useRef } from 'react';
import { Country, AppTheme, Channel, AppSettings } from '../types';
import { Search, Globe, X, Tv, Radio, Palette, Upload, Volume2, VolumeX, Settings, Music, Star, ChevronDown, ChevronUp } from 'lucide-react';

interface SidebarProps {
  countries: Country[];
  selectedCountry: Country | null;
  onSelectCountry: (country: Country) => void;
  isOpen: boolean;
  onClose: () => void;
  mode: 'tv' | 'radio';
  onModeChange: (mode: 'tv' | 'radio') => void;
  themes: AppTheme[];
  currentTheme: AppTheme;
  onThemeChange: (theme: AppTheme) => void;
  favorites: Channel[];
  onSelectFavorite: (channel: Channel) => void;
  onImportM3U: (content: string) => void;
  settings: AppSettings;
  onToggleSound: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
    countries, 
    selectedCountry, 
    onSelectCountry,
    isOpen,
    onClose,
    mode,
    onModeChange,
    themes,
    currentTheme,
    onThemeChange,
    favorites,
    onSelectFavorite,
    onImportM3U,
    settings,
    onToggleSound
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [showThemes, setShowThemes] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showFavorites, setShowFavorites] = useState(true); // Default open if convenient
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCountries = useMemo(() => {
    if (!searchQuery) return countries;
    const lowerQ = searchQuery.toLowerCase();
    return countries.filter(c => 
      c.name.toLowerCase().includes(lowerQ) || 
      c.code.toLowerCase().includes(lowerQ)
    );
  }, [countries, searchQuery]);

  const modeFavorites = useMemo(() => {
      return favorites.filter(c => (c.type || 'tv') === mode);
  }, [favorites, mode]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
          const content = event.target?.result as string;
          if (content) {
              onImportM3U(content);
              if (window.innerWidth < 768) onClose();
          }
      };
      reader.readAsText(file);
      e.target.value = '';
  };

  const { styles } = currentTheme;

  return (
    <>
        {isOpen && (
            <div 
                className="fixed inset-0 bg-black/60 z-40 md:hidden backdrop-blur-sm"
                onClick={onClose}
            />
        )}

        <aside className={`
            fixed md:relative z-50 h-full ${styles.bgSidebar} w-80 flex flex-col
            transition-all duration-300 ease-in-out
            ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
            ${styles.shadow}
        `}>
        <div className={`p-4 border-b ${styles.border} flex items-center justify-between`}>
            <div className={`flex items-center gap-2 ${styles.textMain}`}>
                <Globe className="w-6 h-6" />
                <h1 className="text-xl font-bold tracking-tight">全球看听</h1>
            </div>
            <button onClick={onClose} className={`md:hidden ${styles.textDim} hover:${styles.textMain}`}>
                <X className="w-6 h-6" />
            </button>
        </div>

        <div className="p-4 space-y-3 shrink-0">
            {/* Mode Switcher */}
            <div className={`flex p-1 ${styles.layoutShape} ${currentTheme.type === 'web95' ? styles.border : 'bg-black/10'}`}>
                <button 
                    onClick={() => onModeChange('tv')}
                    className={`flex-1 flex items-center justify-center gap-2 py-2 ${styles.layoutShape} text-sm font-medium transition-all ${mode === 'tv' ? styles.buttonActive : styles.textDim}`}
                >
                    <Tv className="w-4 h-4" /> TV
                </button>
                <button 
                    onClick={() => onModeChange('radio')}
                    className={`flex-1 flex items-center justify-center gap-2 py-2 ${styles.layoutShape} text-sm font-medium transition-all ${mode === 'radio' ? styles.buttonActive : styles.textDim}`}
                >
                    <Radio className="w-4 h-4" /> Radio
                </button>
            </div>

            {/* Settings Toggles */}
            <div>
                 <button 
                    onClick={() => setShowSettings(!showSettings)}
                    className={`flex items-center justify-between w-full px-3 py-2 text-sm ${styles.button} ${styles.border} ${styles.layoutShape}`}
                 >
                    <span className="flex items-center gap-2"><Settings className="w-4 h-4" /> 设置</span>
                    <span>{showSettings ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}</span>
                 </button>

                 {showSettings && (
                    <div className={`mt-2 p-2 ${styles.card} ${styles.layoutShape} flex flex-col gap-2 z-10`}>
                        <button
                            onClick={onToggleSound}
                            className={`flex items-center justify-between w-full px-3 py-2 text-xs ${styles.layoutShape} ${styles.button} hover:bg-white/5 transition-colors`}
                        >
                            <span className="flex items-center gap-2">
                                {settings.enableSound ? <Volume2 className="w-3 h-3 text-green-500" /> : <VolumeX className="w-3 h-3 text-red-500" />}
                                信号连接提示音
                            </span>
                            <div className={`w-8 h-4 rounded-full p-0.5 transition-colors ${settings.enableSound ? 'bg-green-500' : 'bg-gray-600'}`}>
                                <div className={`w-3 h-3 bg-white rounded-full shadow-sm transition-transform ${settings.enableSound ? 'translate-x-4' : 'translate-x-0'}`}></div>
                            </div>
                        </button>
                    </div>
                 )}
            </div>

            {/* Theme Selector */}
            <div>
                 <button 
                    onClick={() => setShowThemes(!showThemes)}
                    className={`flex items-center justify-between w-full px-3 py-2 text-sm ${styles.button} ${styles.border} ${styles.layoutShape}`}
                 >
                    <span className="flex items-center gap-2"><Palette className="w-4 h-4" /> 风格切换</span>
                    <span>{showThemes ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}</span>
                 </button>

                 {showThemes && (
                    <div className={`mt-2 p-2 ${styles.card} ${styles.layoutShape} grid grid-cols-1 gap-1 z-10`}>
                        {themes.map(t => (
                            <button
                                key={t.id}
                                onClick={() => onThemeChange(t)}
                                className={`
                                    w-full text-left px-3 py-2 text-xs ${styles.layoutShape} transition-all
                                    ${currentTheme.id === t.id ? styles.buttonActive : `${styles.textDim} hover:${styles.textMain} hover:bg-white/5`}
                                `}
                            >
                                {t.name}
                            </button>
                        ))}
                    </div>
                 )}
            </div>

            {/* Favorites Section - Moved Here */}
            <div>
                 <button 
                    onClick={() => setShowFavorites(!showFavorites)}
                    className={`flex items-center justify-between w-full px-3 py-2 text-sm ${styles.button} ${styles.border} ${styles.layoutShape}`}
                 >
                    <span className="flex items-center gap-2"><Star className="w-4 h-4" /> 收藏夹 ({modeFavorites.length})</span>
                    <span>{showFavorites ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}</span>
                 </button>

                 {showFavorites && modeFavorites.length > 0 && (
                    <div className={`mt-2 p-2 ${styles.card} ${styles.layoutShape} z-10 space-y-1 max-h-48 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
                        {modeFavorites.map(channel => (
                            <button
                                key={channel.id}
                                onClick={() => {
                                    onSelectFavorite(channel);
                                    if (window.innerWidth < 768) onClose();
                                }}
                                className={`w-full flex items-center gap-2 p-1.5 ${styles.layoutShape} transition-all hover:bg-white/10 text-left`}
                            >
                                <div className="w-5 h-5 rounded flex items-center justify-center bg-black/10 shrink-0 overflow-hidden border border-white/10">
                                    {channel.logo ? (
                                        <img src={channel.logo} alt={channel.name} className="w-full h-full object-contain" />
                                    ) : (
                                        mode === 'tv' ? <Tv className="w-3 h-3 opacity-50" /> : <Music className="w-3 h-3 opacity-50" />
                                    )}
                                </div>
                                <span className={`text-xs font-medium truncate flex-1 ${styles.textMain}`}>{channel.name}</span>
                            </button>
                        ))}
                    </div>
                 )}
                 {showFavorites && modeFavorites.length === 0 && (
                     <div className={`mt-2 p-3 ${styles.card} ${styles.layoutShape} text-center text-xs ${styles.textDim}`}>
                         暂无收藏{mode === 'tv' ? '频道' : '电台'}
                     </div>
                 )}
            </div>

            <button 
                onClick={() => fileInputRef.current?.click()}
                className={`w-full flex items-center justify-center gap-2 py-2 ${styles.layoutShape} ${styles.border} ${styles.button} text-xs transition-colors`}
            >
                <Upload className="w-3 h-3" /> 导入 M3U 列表
            </button>
            <input 
                type="file" 
                accept=".m3u,.m3u8" 
                ref={fileInputRef} 
                className="hidden" 
                onChange={handleFileUpload}
            />
        </div>

        {/* Scrollable List - Countries only */}
        <div className={`flex-1 overflow-y-auto p-4 pt-0 space-y-4 ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>

            {/* Country List */}
            <div className="space-y-2">
                <div className={`relative ${styles.input} ${styles.layoutShape} ${styles.border} flex items-center px-3 py-2 sticky top-0 z-10 shadow-sm`}>
                    <Search className={`w-4 h-4 ${styles.textDim}`} />
                    <input 
                        type="text" 
                        placeholder="搜索国家..." 
                        className="bg-transparent border-none focus:outline-none text-sm w-full ml-2 placeholder-opacity-50"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>

                <div className="space-y-1">
                    {filteredCountries.map(country => (
                        <button
                            key={country.code}
                            onClick={() => {
                                onSelectCountry(country);
                                if (window.innerWidth < 768) onClose();
                            }}
                            className={`
                                w-full flex items-center gap-3 p-2 ${styles.layoutShape} transition-all
                                ${selectedCountry?.code === country.code 
                                    ? styles.buttonActive
                                    : `${styles.textDim} hover:${styles.textMain} hover:bg-white/5`
                                }
                            `}
                        >
                            <span className="text-xl shrink-0">{country.flag}</span>
                            <span className="text-sm font-medium truncate">{country.name}</span>
                            {selectedCountry?.code === country.code && (
