```tsx
import React from 'react';
import { Channel, AppTheme } from '../types';
import { Star, Tv, Radio, Play } from 'lucide-react';

interface FavoritesBarProps {
  favorites: Channel[];
  currentChannel: Channel | null;
  onSelectChannel: (channel: Channel) => void;
  theme: AppTheme;
  mode: 'tv' | 'radio';
}

export const FavoritesBar: React.FC<FavoritesBarProps> = ({
  favorites,
  currentChannel,
  onSelectChannel,
  theme,
  mode
}) => {
  if (favorites.length === 0) return null;

  const { styles } = theme;
  const filteredFavorites = favorites.filter(c => (c.type || 'tv') === mode);

  if (filteredFavorites.length === 0) return null;

  return (
    <div className={`w-full mb-4 shrink-0`}>
      <div className={`flex items-center gap-2 mb-2 px-1`}>
        <Star className={`w-4 h-4 text-yellow-500 fill-yellow-500`} />
        <h3 className={`text-xs font-bold uppercase tracking-wider ${styles.textDim}`}>快捷收藏栏</h3>
      </div>

      <div className={`
        flex gap-3 overflow-x-auto pb-2 scrollbar-hide
        ${theme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}
      `}>
        {filteredFavorites.map(channel => {
            const isActive = currentChannel?.id === channel.id;
            return (
                <button
                    key={channel.id}
                    onClick={() => onSelectChannel(channel)}
                    className={`
                        group flex items-center gap-2 px-3 py-2 shrink-0 max-w-[160px]
                        ${styles.layoutShape} transition-all duration-200
                        ${isActive 
                            ? `${styles.buttonActive} border-l-4 border-l-yellow-400` 
                            : `${styles.card} hover:bg-white/10`}
                        ${theme.type === 'web95' && isActive ? 'border-2 border-white' : ''}
                    `}
                >
