                    theme={currentTheme}
                    favorites={favorites}
                    onToggleFavorite={toggleFavorite}
                />
            </div>
        </div>
      </main>

      {/* Schedule Modal */}
      <ScheduleList 
        reminders={reminders}
        isOpen={showSchedule}
        onClose={() => setShowSchedule(false)}
        onDelete={handleDeleteReminder}
        theme={currentTheme}
