        setSignalStrength(0);
        setIsPlaying(false);
        return;
    }

    if (isRecording) handleStopRecording();
    setSignalStrength(1); 
    setShowTranslate(false);
    setError(null);
    setLoading(true);
    setIsPlaying(false);
    setShowAlarmPicker(false);

    const handleMediaError = () => {
        if (video.networkState === 3) { 
             setError(isRadio ? "电台无法连接" : "直播流无法播放");
             setLoading(false);
             setSignalStrength(0);
        }
    };

    const handleWaiting = () => {
        setLoading(true);
        setSignalStrength(2); 
    };

    const handlePlaying = () => {
        setLoading(false);
        setIsPlaying(true);
        setError(null);
        setSignalStrength(4); 
    };

    const handleCanPlay = () => {
        if (autoPlay) {
            video.play().catch((e) => console.log("Autoplay prevented", e));
        }
    };

    if (hlsRef.current) {
        hlsRef.current.destroy();
        hlsRef.current = null;
    }

    const isHlsSource = url.includes('.m3u8');

    if (isHlsSource && Hls.isSupported()) {
      hls = new Hls({
        enableWorker: true,
        lowLatencyMode: true,
        backBufferLength: 90,
      });
      hlsRef.current = hls;

      hls.loadSource(url);
      hls.attachMedia(video);

      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        if (autoPlay) {
            video.play().catch(() => {});
        }
      });

      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
          switch (data.type) {
            case Hls.ErrorTypes.NETWORK_ERROR:
              setSignalStrength(1);
              hls?.startLoad();
              break;
            case Hls.ErrorTypes.MEDIA_ERROR:
              setSignalStrength(2);
              hls?.recoverMediaError();
              break;
            default:
              hls?.destroy();
              setError("播放源致命错误");
              break;
          }
        }
      });
    } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
      video.src = url;
    } else {
      video.src = url;
    }

    video.addEventListener('error', handleMediaError);
    video.addEventListener('waiting', handleWaiting);
    video.addEventListener('playing', handlePlaying);
    video.addEventListener('canplay', handleCanPlay);

    return () => {
      if (hls) hls.destroy();
      video.removeEventListener('error', handleMediaError);
      video.removeEventListener('waiting', handleWaiting);
      video.removeEventListener('playing', handlePlaying);
      video.removeEventListener('canplay', handleCanPlay);
    };
  }, [url, isRadio, autoPlay]);

  const togglePlay = () => {
    if (!videoRef.current) return;
    if (isPlaying) {
      videoRef.current.pause();
      setIsPlaying(false);
    } else {
      videoRef.current.play();
      setIsPlaying(true);
    }
  };

  const handleStartRecording = () => {
    const video = videoRef.current;
    if (!video) return;

    try {
        const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;

        if (!stream) {
            alert("您的浏览器不支持直接录制此媒体流。");
            return;
        }

        const mimeType = MediaRecorder.isTypeSupported('video/webm; codecs=vp9') 
            ? 'video/webm; codecs=vp9' 
            : 'video/webm';

        const mediaRecorder = new MediaRecorder(stream, { mimeType });
        mediaRecorderRef.current = mediaRecorder;
        chunksRef.current = [];

        mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) {
                chunksRef.current.push(e.data);
            }
        };

        mediaRecorder.onstop = async () => {
            const blob = new Blob(chunksRef.current, { type: 'video/webm' });
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            const filename = `${channel?.name || 'recording'}-${timestamp}.webm`;

            setIsRecording(false);

            let saved = false;

            // Attempt to use File System Access API to prompt user for save location
            // @ts-ignore
            if (window.showSaveFilePicker) {
                try {
                    // @ts-ignore
                    const handle = await window.showSaveFilePicker({
                        suggestedName: filename,
                        types: [{
                            description: 'WebM Video',
                            accept: { 'video/webm': ['.webm'] },
                        }],
                    });
                    // @ts-ignore
                    const writable = await handle.createWritable();
                    await writable.write(blob);
                    await writable.close();
                    saved = true;
                } catch (err) {
                    const error = err as Error;
                    // If user aborted, we do NOT fallback to auto download. We just stop.
                    if (error.name === 'AbortError') {
                        return;
                    }
                    // For SecurityError/Cross-Origin errors or others, we fallback to auto-download
                    console.warn("Save picker failed or blocked, falling back to auto-download:", error.message);
                    saved = false;
                }
            }

            // Fallback to automatic download if picker failed or unavailable
            if (!saved) {
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                document.body.appendChild(a);
                a.style.display = 'none';
                a.href = url;
                a.download = filename;
                a.click();
                window.URL.revokeObjectURL(url);
                a.remove();
            }
        };

        mediaRecorder.start();
        setIsRecording(true);
    } catch (e) {
        console.error("Recording failed:", e);
        alert("无法录制。可能是由于版权保护(CORS)或浏览器限制。");
    }
  };

  const handleStopRecording = () => {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
          mediaRecorderRef.current.stop();
      }
  };

  const handleSaveReminder = () => {
