export const getTimezone = (countryCode: string): string => {
  return TIMEZONE_MAP[countryCode] || 'UTC';
};

export const fetchCountries = async (): Promise<Country[]> => {
  try {
    const response = await fetch(`${API_BASE}/countries.json`);
    if (!response.ok) throw new Error('Failed to fetch countries');
    const data = await response.json();
    const validData = data.filter((c: Country) => c.code && c.name);
    return validData.sort((a: Country, b: Country) => a.name.localeCompare(b.name));
  } catch (error) {
    return FALLBACK_COUNTRIES.sort((a, b) => a.name.localeCompare(b.name));
  }
};

export const fetchChannelsByCountry = async (countryCode: string, refresh = false): Promise<Channel[]> => {
  try {
    const cacheBuster = refresh ? `?t=${Date.now()}` : '';
    const response = await fetch(`${PLAYLIST_BASE}/${countryCode.toLowerCase()}.m3u${cacheBuster}`);

    if (!response.ok) {
        // Check if we have fallback data for this country
        if (FALLBACK_CHANNELS[countryCode]) {
            return FALLBACK_CHANNELS[countryCode];
        }
        return [];
    }

    const text = await response.text();
    const channels = parseM3U(text);

    // If parsed list is empty (bad file), try fallback
    if (channels.length === 0 && FALLBACK_CHANNELS[countryCode]) {
        return FALLBACK_CHANNELS[countryCode];
    }

    return channels.map(c => ({ ...c, type: 'tv' }));
  } catch (error) {
    // Network error -> Return Fallback
    if (FALLBACK_CHANNELS[countryCode]) {
        return FALLBACK_CHANNELS[countryCode];
    }
    return [];
  }
};

export const fetchRadioStations = async (countryCode: string, refresh = false): Promise<Channel[]> => {
  try {
    const url = `${RADIO_API_BASE}/${countryCode}${refresh ? '?hidebroken=true&limit=500' : ''}`;
    const response = await fetch(url);
    if (!response.ok) return [];

    const data = await response.json();

    return data.map((station: any) => ({
      id: station.stationuuid,
      name: station.name.trim(),
      logo: station.favicon || null,
      url: station.url_resolved,
      group: station.tags || 'Radio',
      type: 'radio' as const
    }));
  } catch (error) {
    return [];
  }
};

export const parseM3U = (content: string): Channel[] => {
  const lines = content.split('\n');
  const channels: Channel[] = [];

  let currentChannel: Partial<Channel> = {};

  for (let line of lines) {
    line = line.trim();
    if (!line) continue;

    if (line.startsWith('#EXTINF:')) {
      const infoPart = line.substring(8);
      const commaIndex = infoPart.lastIndexOf(',');
      const displayName = infoPart.substring(commaIndex + 1).trim();

      const logoMatch = infoPart.match(/tvg-logo="([^"]*)"/);
      const groupMatch = infoPart.match(/group-title="([^"]*)"/);

      let hash = 0;
      for (let i = 0; i < displayName.length; i++) {
        hash = ((hash << 5) - hash) + displayName.charCodeAt(i);
        hash |= 0;
      }
      const id = `ch-${Math.abs(hash)}`;

      currentChannel = {
        name: displayName,
        logo: logoMatch ? logoMatch[1] : null,
        group: groupMatch ? groupMatch[1] : 'General',
        id: id
      };
    } else if (!line.startsWith('#')) {
      if (currentChannel.name) {
        let hash = 0;
        const combo = currentChannel.name + line;
        for (let i = 0; i < combo.length; i++) {
           hash = ((hash << 5) - hash) + combo.charCodeAt(i);
           hash |= 0;
        }

        channels.push({
          ...currentChannel as Channel,
          id: `ch-${Math.abs(hash)}`,
          url: line
        });
        currentChannel = {};
      }
    }
  }

  return channels;
};

To fix the "Stream Error" which is likely caused by CORS restrictions blocking playback when `crossOrigin="anonymous"` is enforced on non-CORS compliant IPTV streams, I will remove the `crossOrigin` attribute from the video element. This ensures wider compatibility with streams. I will also refine the error logging.

# Updated files:

## components/VideoPlayer.tsx

1.  **Remove `crossOrigin="anonymous"`** from the `<video>` tags. This allows the browser to play opaque streams (streams without CORS headers), fixing the playback error. Note that this may restrict recording functionality for some streams due to browser security policies, but playback is prioritized.
2.  **Refine `onError` logging** to avoid printing `[object Object]`.

