## index.tsx

添加了 `ErrorBoundary`（错误边界）。这意味着即使代码中有 Bug，屏幕上也不会显示一片空白，而是会显示具体的错误信息，方便您定位问题。

```tsx
import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

// Error Boundary to catch runtime errors and prevent white screen
class ErrorBoundary extends React.Component<{children: React.ReactNode}, {hasError: boolean, error: Error | null}> {
  constructor(props: {children: React.ReactNode}) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Uncaught error in application:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ 
          padding: '40px', 
          color: '#fff', 
          background: '#111', 
          height: '100vh', 
          fontFamily: 'monospace',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          textAlign: 'center'
        }}>
          <h1 style={{ fontSize: '24px', marginBottom: '20px', color: '#ff5555' }}>Application Crashed</h1>
          <p style={{ marginBottom: '10px' }}>The application encountered a critical error.</p>
          <pre style={{ 
            background: '#333', 
            padding: '15px', 
            borderRadius: '5px', 
            color: '#ffaaaa', 
            maxWidth: '80%', 
            overflow: 'auto',
            textAlign: 'left'
          }}>
            {this.state.error?.toString()}
          </pre>
          <button 
            onClick={() => window.location.reload()} 
            style={{
              marginTop: '20px',
              padding: '10px 20px',
              background: '#fff',
              color: '#000',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontWeight: 'bold'
            }}
          >
            Reload Page
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const rootElement = document.getElementById('root');
if (!rootElement) {
  document.body.innerHTML = '<div style="color:red; padding:20px;">Fatal Error: Root element not found.</div>';
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <ErrorBoundary>
      <App />
    </ErrorBoundary>
  </React.StrictMode>
);
