                    {showThemes && (
                        <div className={`absolute bottom-full right-0 w-48 mb-2 p-2 ${styles.card} ${styles.layoutShape} grid grid-cols-1 gap-1 z-50 shadow-xl`}>
                            {themes.map(t => (
