                ></div>

                <div className="max-w-[1600px] mx-auto relative z-10">

                    {/* Header Info */}
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-xl ${currentTheme.styles.card}`}>
