                            </div>
                            <div>
                                <h2 className={`text-3xl font-black tracking-tight bg-gradient-to-r from-white to-white/60 bg-clip-text text-transparent ${currentTheme.type === 'web95' ? 'text-black bg-none' : ''}`}>
                                    {selectedCountry ? selectedCountry.name : '全球看听'}
