            `}
        >
            {/* 收藏按钮 */}
            <button
                onClick={(e) => {
                    e.stopPropagation();
                    onToggleFavorite(channel);
                }}
                className={`absolute top-1 right-1 z-20 p-1.5 rounded-full transition-all duration-200 
                    ${isFavorite 
