                    }`}
                title={isFavorite ? "取消收藏" : "收藏频道"}
            >
                <Star className={`w-3.5 h-3.5 ${isFavorite ? 'fill-yellow-400' : 'fill-none'}`} />
            </button>

            {/* 主点击区域 */}
            <button
                onClick={() => onSelectChannel(channel)}
                className="w-full flex flex-col items-center p-3 h-full text-center"
