interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  autoPlay?: boolean;
  isRadio?: boolean;
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAddReminder: (channel: Channel, time: string) => void;
  settings?: { enableSound: boolean };
  isSticky?: boolean;
  onCloseSticky?: () => void;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, 
    country,
    autoPlay = true, 
    isRadio = false, 
    theme,
    isFavorite,
    onToggleFavorite,
    onAddReminder,
    settings = { enableSound: true },
    isSticky = false,
    onCloseSticky
}) => {
  const { styles } = theme;

  // Dual Video Engine State
  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);

  // General State
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);

  // Volume State
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);

  // Recording State
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  // Features State
  const [signalStrength, setSignalStrength] = useState<number>(0); 
  const [showTranslate, setShowTranslate] = useState(false);
  const [currentTimeStr, setCurrentTimeStr] = useState('');

  // Cast State
  const [canCast, setCanCast] = useState(false);
  const [isCasting, setIsCasting] = useState(false);

  // Alarm State
  const [showAlarmPicker, setShowAlarmPicker] = useState(false);
  const [alarmTime, setAlarmTime] = useState('');

  // Audio Context for Tick Sound
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Helper: Play Tick Sound
  const playTick = useCallback(() => {
      if (!settings.enableSound) return;
      try {
          if (!audioCtxRef.current) {
              audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
          }
          const ctx = audioCtxRef.current;
          if (ctx.state === 'suspended') ctx.resume();

          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.frequency.setValueAtTime(880, ctx.currentTime); // A5
          osc.type = 'sine';

          gain.gain.setValueAtTime(0.05, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);

          osc.start();
          osc.stop(ctx.currentTime + 0.06);
      } catch (e) {
          // Ignore audio errors
      }
  }, [settings.enableSound]);

  // Update Clock based on country
  useEffect(() => {
    if (!country && !channel) return;
    const tz = country ? getTimezone(country.code) : 'UTC';

    const updateTime = () => {
        try {
            const now = new Date();
            const timeString = new Intl.DateTimeFormat('en-US', {
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false,
                timeZone: tz
            }).format(now);
            setCurrentTimeStr(timeString);
        } catch (e) {
            setCurrentTimeStr(new Date().toLocaleTimeString('en-GB'));
        }
    };

    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, [country, channel]);

  // Volume Sync
  useEffect(() => {
      videoRefs.forEach(ref => {
          if (ref.current) {
              ref.current.volume = volume;
              ref.current.muted = isMuted;
          }
      });
  }, [volume, isMuted]);

  // Check for Remote Playback API support
  useEffect(() => {
      const video = videoRefs[activePlayerIndex].current;
      if (video && 'remote' in video) {
          // @ts-ignore - Remote Playback API
          video.remote.watchAvailability((available) => {
              setCanCast(available);
          }).catch(() => {
              setCanCast(false); 
          });
      }
  }, [activePlayerIndex]);

  // --- DUAL ENGINE LOADING LOGIC ---
  useEffect(() => {
    const url = channel?.url;

    if (!url) {
        setLoading(false); 
        setSignalStrength(0);
        setIsPlaying(false);
        return;
    }

    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    const currentVideo = videoRefs[activePlayerIndex].current;

    if (!nextVideo) return;

    if (isRecording) handleStopRecording();

    setSignalStrength(1); 
    setShowTranslate(false);
    setError(null);
    if (!currentVideo || currentVideo.paused || currentVideo.ended) {
        setLoading(true);
    }

    setShowAlarmPicker(false);

    if (hlsRefs.current[nextIndex]) {
        hlsRefs.current[nextIndex]?.destroy();
        hlsRefs.current[nextIndex] = null;
    }

    const isHlsSource = url.includes('.m3u8');
    let hls: Hls | null = null;

    const onReadyToSwitch = () => {
        playTick(); 
        setActivePlayerIndex(nextIndex);
        setIsPlaying(true);
        setLoading(false);
        setSignalStrength(4);

        if (autoPlay) {
            nextVideo.play().catch(e => console.log("Autoplay prevented", e));
        }

        setTimeout(() => {
            if (currentVideo) {
                currentVideo.pause();
                currentVideo.removeAttribute('src');
                currentVideo.load(); 
            }
            if (hlsRefs.current[activePlayerIndex]) {
                hlsRefs.current[activePlayerIndex]?.destroy();
                hlsRefs.current[activePlayerIndex] = null;
            }
        }, 500); 
    };

    const onError = (e: any) => {
        // Improve error logging
        const msg = e instanceof Event ? (e.type === 'error' ? 'Network/Format Error' : e.type) : e;
        console.warn("Stream Error:", msg);

        if (activePlayerIndex !== nextIndex) {
             setActivePlayerIndex(nextIndex);
        }
        setError(isRadio ? "电台无法连接" : "直播流无法播放");
        setLoading(false);
        setSignalStrength(0);
    };

    const cleanupListeners = () => {
        nextVideo.removeEventListener('error', onError);
        nextVideo.removeEventListener('canplay', onReadyToSwitch);
    };

    nextVideo.addEventListener('error', onError);
    nextVideo.addEventListener('canplay', onReadyToSwitch);

    if (isHlsSource && Hls.isSupported()) {
      hls = new Hls({
        enableWorker: true,
        lowLatencyMode: true,
        backBufferLength: 90,
      });
      hlsRefs.current[nextIndex] = hls;

      hls.loadSource(url);
      hls.attachMedia(nextVideo);

      hls.on(Hls.Events.MANIFEST_PARSED, () => {
         if (autoPlay) nextVideo.play().catch(() => {});
      });

      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
          switch (data.type) {
            case Hls.ErrorTypes.NETWORK_ERROR:
              hls?.startLoad();
              break;
            case Hls.ErrorTypes.MEDIA_ERROR:
              hls?.recoverMediaError();
              break;
            default:
              onError(data);
              hls?.destroy();
              break;
          }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.load();
    }

    return () => {
        cleanupListeners();
    };

  }, [channel?.url, channel?.id]);

  const togglePlay = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;
    if (isPlaying) {
      video.pause();
      setIsPlaying(false);
    } else {
      video.play();
      setIsPlaying(true);
    }
  };

  const handleCast = async () => {
      const video = videoRefs[activePlayerIndex].current;
      if (video && 'remote' in video) {
          try {
              // @ts-ignore
              if (video.remote.state === 'disconnected') {
                  // @ts-ignore
                  await video.remote.prompt();
                  setIsCasting(true);
              } else {
                  // @ts-ignore
                  await video.remote.prompt(); // Toggling off usually handled by browser UI, but calling prompt brings it up
                  setIsCasting(false);
              }
          } catch (e) {
              console.error("Cast failed", e);
          }
      } else {
          alert("您的浏览器不支持投屏功能，请尝试使用 Chrome 或 Edge。");
      }
  };

  const handleStartRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;

    try {
        const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;

        if (!stream) {
            alert("您的浏览器不支持直接录制此媒体流。");
            return;
        }

        const mimeType = MediaRecorder.isTypeSupported('video/webm; codecs=vp9') 
            ? 'video/webm; codecs=vp9' 
            : 'video/webm';

        const mediaRecorder = new MediaRecorder(stream, { mimeType });
        mediaRecorderRef.current = mediaRecorder;
        chunksRef.current = [];

        mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) {
                chunksRef.current.push(e.data);
            }
        };

        mediaRecorder.onstop = async () => {
            const blob = new Blob(chunksRef.current, { type: 'video/webm' });
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            const filename = `${channel?.name || 'recording'}-${timestamp}.webm`;

            setIsRecording(false);

            // @ts-ignore
            if (window.showSaveFilePicker) {
                try {
                    // @ts-ignore
                    const handle = await window.showSaveFilePicker({
                        suggestedName: filename,
                        types: [{
                            description: 'WebM Video',
                            accept: { 'video/webm': ['.webm'] },
                        }],
                    });
                    // @ts-ignore
                    const writable = await handle.createWritable();
                    await writable.write(blob);
                    await writable.close();
                    return;
                } catch (err) {
                    if ((err as Error).name === 'AbortError') return;
                    console.warn("Save picker failed, fallback to download");
                }
            }

            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            document.body.appendChild(a);
            a.style.display = 'none';
            a.href = url;
            a.download = filename;
            a.click();
            window.URL.revokeObjectURL(url);
            a.remove();
        };

        mediaRecorder.start();
        setIsRecording(true);
    } catch (e) {
        console.error("Recording failed:", e);
        alert("无法录制。可能是由于版权保护(CORS)或浏览器限制。");
    }
  };

  const handleStopRecording = () => {
