                     <div className="bg-[#c0c0c0] w-4 h-4 text-[10px] text-black border border-white border-b-black border-r-black flex items-center justify-center">×</div>
                 </div>
             </div>
        )}

        {/* DUAL VIDEO PLAYERS - Removed crossOrigin to fix stream errors */}
        {[0, 1].map((index) => (
