  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const playUiSound = useCallback(() => {
      if (!settings.enableSound) return;
      try {
          if (!audioCtxRef.current) {
              audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
          }
          const ctx = audioCtxRef.current;
          if (ctx.state === 'suspended') ctx.resume();

          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.type = 'sine';
          osc.frequency.setValueAtTime(600, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.1);
          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
          osc.start();
          osc.stop(ctx.currentTime + 0.1);
      } catch (e) { /* ignore */ }
  }, [settings.enableSound]);

  useEffect(() => {
      const handleGlobalClick = (e: MouseEvent) => {
          const target = e.target as HTMLElement;
          const interactive = target.closest('button') || target.closest('a') || target.closest('input') || target.closest('[role="button"]');
          if (interactive) playUiSound();
      };
      window.addEventListener('click', handleGlobalClick, true); 
      return () => window.removeEventListener('click', handleGlobalClick, true);
  }, [playUiSound]);

  useEffect(() => {
      const observer = new IntersectionObserver(
          ([entry]) => {
              if (!stickyEnabled) {
                  setIsSticky(false);
                  return;
              }
              setIsSticky(!entry.isIntersecting);
          },
          { threshold: 0, rootMargin: "-100px 0px 0px 0px" } 
      );

      if (playerMarkerRef.current) {
          observer.observe(playerMarkerRef.current);
      }

      return () => observer.disconnect();
  }, [stickyEnabled]);

  useEffect(() => {
      try {
          const savedFavs = localStorage.getItem('global_favorites');
          if (savedFavs) setFavorites(JSON.parse(savedFavs));
          const savedRems = localStorage.getItem('global_reminders');
          if (savedRems) setReminders(JSON.parse(savedRems));
      } catch (e) { console.warn(e); }
      setIsAppReady(true);
  }, []);

  useEffect(() => {
      if (isAppReady) {
        localStorage.setItem('global_favorites', JSON.stringify(favorites));
        localStorage.setItem('global_reminders', JSON.stringify(reminders));
      }
  }, [favorites, reminders, isAppReady]);

  useEffect(() => {
    if (selectedCountry?.code === 'FAVORITES') {
        setChannels(favorites.filter(c => (c.type || 'tv') === mode));
    }
  }, [favorites, selectedCountry, mode]);

  useEffect(() => {
    const interval = setInterval(() => {
        const now = new Date();
        const currentHours = now.getHours().toString().padStart(2, '0');
        const currentMinutes = now.getMinutes().toString().padStart(2, '0');
        const currentTimeStr = `${currentHours}:${currentMinutes}`;
        reminders.forEach(reminder => {
            if (reminder.timeStr === currentTimeStr) {
                 const lastAlerted = sessionStorage.getItem(`alerted_${reminder.id}_${currentTimeStr}`);
                 if (!lastAlerted) {
                     setActiveReminder(reminder);
                     sessionStorage.setItem(`alerted_${reminder.id}_${currentTimeStr}`, 'true');
                 }
            }
        });
    }, 10000); 
    return () => clearInterval(interval);
  }, [reminders]);

  useEffect(() => {
    const loadCountries = async () => {
      try {
        const data = await fetchCountries();
        setCountries([FAVORITES_COUNTRY, ...data]);
        // Default to US or the first one (exclude China automatically via fetchCountries filter)
        let defaultCountry = data.find(c => c.code === 'US') || data[0];
        if (defaultCountry) setSelectedCountry(defaultCountry);
        else setSelectedCountry(FAVORITES_COUNTRY);
      } catch (err) {
        setCountries([FAVORITES_COUNTRY]);
        setSelectedCountry(FAVORITES_COUNTRY);
      } finally {
        setLoadingCountries(false);
      }
    };
    if (isAppReady) loadCountries();
  }, [isAppReady]);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;
    if (selectedCountry.code === 'CUSTOM') {
        setChannels(customChannels);
        setLoadingChannels(false);
        return;
    }
    if (selectedCountry.code === 'FAVORITES') {
        setChannels(favorites.filter(c => (c.type || 'tv') === mode));
        setLoadingChannels(false);
        return;
    }
    setLoadingChannels(true);
    if (!refresh) setChannels([]);
    try {
        let data: Channel[] = [];
        if (mode === 'tv') data = await fetchChannelsByCountry(selectedCountry.code, refresh);
        else data = await fetchRadioStations(selectedCountry.code, refresh);
        setChannels(data);
    } catch (err) { setChannels([]); } 
    finally { setLoadingChannels(false); }
  };

  useEffect(() => { loadContent(); }, [selectedCountry, mode]);

  const handleCountrySelect = (country: Country) => { setSelectedCountry(country); setSidebarOpen(false); };
  const handleModeChange = (newMode: 'tv' | 'radio') => { if (mode !== newMode) { setMode(newMode); setSidebarOpen(false); } };
  const handleChannelSelect = (channel: Channel) => { setCurrentChannel(channel); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const toggleFavorite = (channel: Channel) => {
      setFavorites(prev => {
          const exists = prev.some(c => c.id === channel.id);
          if (exists) return prev.filter(c => c.id !== channel.id);
          return [...prev, { ...channel, type: channel.type || mode }];
      });
  };
  const isFavorite = (channel: Channel | null) => !!channel && favorites.some(c => c.id === channel.id);
  const handleAddReminder = (channel: Channel, time: string) => {
    setReminders(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), channelId: channel.id, channelName: channel.name, timeStr: time, created: Date.now() }]);
    alert(`已设置提醒: ${channel.name} @ ${time}`);
  };
  const handleDeleteReminder = (id: string) => setReminders(prev => prev.filter(r => r.id !== id));
  const handlePlayFromSchedule = (channelId: string) => {
      let channel = channels.find(c => c.id === channelId) || favorites.find(c => c.id === channelId);
      if (channel) { setCurrentChannel(channel); setActiveReminder(null); window.scrollTo({ top: 0, behavior: 'smooth' }); }
      else alert("无法在当前列表中找到该频道。");
  };
  const handleImportM3U = (content: string) => {
      try {
          const parsed = parseM3U(content);
          setCustomChannels(parsed.map(c => ({...c, type: 'tv' as const})));
          if (!countries.find(c => c.code === 'CUSTOM')) setCountries(prev => [CUSTOM_COUNTRY, ...prev]);
          setSelectedCountry(CUSTOM_COUNTRY);
          alert(`成功导入 ${parsed.length} 个频道`);
      } catch (e) { alert("解析文件失败"); }
  };

  if (!isAppReady || !currentTheme) return <div className="flex h-screen w-full items-center justify-center bg-black text-white">Loading...</div>;

  return (
    <div className={`flex h-screen ${currentTheme.styles.bgMain} ${currentTheme.styles.bgPattern} ${currentTheme.styles.font} overflow-hidden transition-colors duration-500 relative`}>
      <div className="bg-noise"></div>

      <Sidebar 
        countries={countries}
        selectedCountry={selectedCountry}
        onSelectCountry={handleCountrySelect}
        isOpen={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        mode={mode}
        onModeChange={handleModeChange}
        themes={THEMES}
        currentTheme={currentTheme}
        onThemeChange={setCurrentTheme}
        favorites={favorites}
        onSelectFavorite={handleChannelSelect}
        onImportM3U={handleImportM3U}
        settings={settings}
        onToggleSound={() => setSettings(prev => ({ ...prev, enableSound: !prev.enableSound }))}
        reminders={reminders}
        onDeleteReminder={handleDeleteReminder}
        onPlayReminder={handlePlayFromSchedule}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative z-10">
        <header className={`md:hidden ${currentTheme.styles.bgSidebar} border-b ${currentTheme.styles.border} p-4 flex items-center justify-between shrink-0 z-30`}>
            <button onClick={() => setSidebarOpen(true)} className={currentTheme.styles.textMain}><Menu className="w-6 h-6" /></button>
            <h1 className={`text-lg font-bold ${currentTheme.styles.textMain}`}>全球实时看和听</h1>
            <div className="flex items-center gap-2">
                <button onClick={() => setShowSchedule(true)} className={currentTheme.styles.textMain}><CalendarClock className="w-5 h-5" /></button>
                <button onClick={() => loadContent(true)} className={currentTheme.styles.textMain}><RefreshCw className={`w-5 h-5 ${loadingChannels ? 'animate-spin' : ''}`} /></button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className={`w-full relative py-6 px-4 md:px-8 shadow-2xl ${currentTheme.type === 'glass' ? 'bg-black/30' : 'bg-black/10'} border-b ${currentTheme.styles.border}`}>
                <div 
                    className="absolute inset-0 opacity-30 pointer-events-none transition-colors duration-1000 blur-3xl animate-pulse-glow"
                    style={{ background: `radial-gradient(circle at center, ${currentTheme.styles.accentColor} 0%, transparent 70%)` }}
                ></div>

                <div className="max-w-[1600px] mx-auto relative z-10">
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-3">
                            <div className={`p-2.5 rounded-xl ${currentTheme.styles.card} backdrop-blur-md shadow-lg border-0`}>
                                <Tv className={`w-6 h-6 ${currentTheme.styles.textMain}`} />
                            </div>
                            <div>
                                <h2 className={`text-3xl font-black tracking-tight bg-gradient-to-r from-white via-white/80 to-white/50 bg-clip-text text-transparent ${currentTheme.type === 'web95' ? 'text-black bg-none' : ''} ${currentTheme.type === 'kids' ? '!text-[#5D4037] !bg-none' : ''}`}>
                                    {selectedCountry ? selectedCountry.name : '全球看听'}
                                </h2>
                                <p className={`text-xs font-bold uppercase tracking-widest ${currentTheme.styles.textDim} mt-1 flex items-center gap-1`}>
                                    <Sparkles className="w-3 h-3" /> {channels.length} 信号源在线
                                </p>
                            </div>
                        </div>
                        <div className="hidden md:flex gap-2">
                            <button onClick={() => setShowSchedule(true)} className={`px-4 py-2 ${currentTheme.styles.button} ${currentTheme.styles.layoutShape} text-sm flex items-center gap-2 font-medium`}><CalendarClock className="w-4 h-4" /> 节目表</button>
                            <button onClick={() => loadContent(true)} className={`px-4 py-2 ${currentTheme.styles.button} ${currentTheme.styles.layoutShape} text-sm flex items-center gap-2 font-medium`}><RefreshCw className={`w-4 h-4 ${loadingChannels ? 'animate-spin' : ''}`} /> 刷新</button>
                        </div>
                    </div>

                    <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />

                    <div ref={playerMarkerRef} className="w-full h-1"></div>

                    <div className="mt-4 min-h-[300px] md:min-h-[450px] relative">
                        <VideoPlayer 
                            channel={currentChannel} 
                            country={selectedCountry} 
                            autoPlay={true} 
                            isRadio={mode === 'radio'} 
                            theme={currentTheme} 
                            isFavorite={isFavorite(currentChannel)} 
                            onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)} 
                            onAddReminder={handleAddReminder} 
                            settings={settings} 
                            isSticky={isSticky}
                            onCloseSticky={() => setStickyEnabled(false)}
                        />
                    </div>
                </div>
            </div>

            <div className="max-w-[1600px] mx-auto p-4 md:p-8">
                <div className="flex items-center gap-3 mb-6 px-1">
                    <div className={`w-1.5 h-8 ${currentTheme.type === 'kids' ? 'bg-[#FF7043]' : currentTheme.styles.buttonPrimary} rounded-full shadow-lg shadow-current opacity-80`}></div>
                    <h3 className={`text-xl font-bold ${currentTheme.styles.textMain}`}>频道导视</h3>
                </div>

                <ChannelGrid channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} onToggleFavorite={toggleFavorite} />
            </div>
        </div>
      </main>

      <ScheduleList reminders={reminders} isOpen={showSchedule} onClose={() => setShowSchedule(false)} onDelete={handleDeleteReminder} theme={currentTheme} onPlayChannel={handlePlayFromSchedule} allChannels={[...channels, ...favorites]} />
      <AlarmModal reminder={activeReminder} onClose={() => setActiveReminder(null)} onWatch={handlePlayFromSchedule} theme={currentTheme} />
      <AiChatPet theme={currentTheme} />
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { AlertCircle, Play, RefreshCw, Radio, Music, Square, Star, Captions, StopCircle, Volume2, VolumeX, Maximize, AlarmClock, Check, Clock, X, Cast } from 'lucide-react';
import { AppTheme, Channel, Country } from '../types';
import { getTimezone } from '../services/iptvService';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  autoPlay?: boolean;
  isRadio?: boolean;
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAddReminder: (channel: Channel, time: string) => void;
  settings?: { enableSound: boolean };
  isSticky?: boolean;
  onCloseSticky?: () => void;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, 
    country,
    autoPlay = true, 
    isRadio = false, 
    theme,
    isFavorite,
    onToggleFavorite,
    onAddReminder,
    settings = { enableSound: true },
    isSticky = false,
    onCloseSticky
}) => {
  const { styles } = theme;

  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);

  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);

  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);

  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const [signalStrength, setSignalStrength] = useState<number>(0); 
  const [showTranslate, setShowTranslate] = useState(false);
  const [currentTimeStr, setCurrentTimeStr] = useState('');

  const [canCast, setCanCast] = useState(false);
  const [isCasting, setIsCasting] = useState(false);

  const [showAlarmPicker, setShowAlarmPicker] = useState(false);
  const [alarmTime, setAlarmTime] = useState('');

  const audioCtxRef = useRef<AudioContext | null>(null);

  const playTick = useCallback(() => {
      if (!settings.enableSound) return;
      try {
          if (!audioCtxRef.current) {
              audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
          }
          const ctx = audioCtxRef.current;
          if (ctx.state === 'suspended') ctx.resume();

          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.frequency.setValueAtTime(880, ctx.currentTime);
          osc.type = 'sine';
          gain.gain.setValueAtTime(0.05, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);
          osc.start();
          osc.stop(ctx.currentTime + 0.06);
      } catch (e) {}
  }, [settings.enableSound]);

  useEffect(() => {
    if (!country && !channel) return;
    const tz = country ? getTimezone(country.code) : 'UTC';

    const updateTime = () => {
        try {
            const now = new Date();
            const timeString = new Intl.DateTimeFormat('en-US', {
                hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: tz
            }).format(now);
            setCurrentTimeStr(timeString);
        } catch (e) {
            setCurrentTimeStr(new Date().toLocaleTimeString('en-GB'));
        }
    };

    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, [country, channel]);

  useEffect(() => {
      videoRefs.forEach(ref => {
          if (ref.current) {
              ref.current.volume = volume;
              ref.current.muted = isMuted;
          }
      });
  }, [volume, isMuted]);

  useEffect(() => {
      const video = videoRefs[activePlayerIndex].current;
      if (video && 'remote' in video) {
          // @ts-ignore
          video.remote.watchAvailability((available: boolean) => {
              setCanCast(available);
          }).catch(() => setCanCast(false));
      }
  }, [activePlayerIndex]);

  useEffect(() => {
    const url = channel?.url;
    if (!url) {
        setLoading(false); 
        setSignalStrength(0);
        setIsPlaying(false);
        return;
    }

    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    const currentVideo = videoRefs[activePlayerIndex].current;
    if (!nextVideo) return;

    if (isRecording) handleStopRecording();
    setSignalStrength(1); 
    setShowTranslate(false);
    setError(null);
    if (!currentVideo || currentVideo.paused || currentVideo.ended) setLoading(true);
    setShowAlarmPicker(false);

    if (hlsRefs.current[nextIndex]) {
        hlsRefs.current[nextIndex]?.destroy();
        hlsRefs.current[nextIndex] = null;
    }

    const isHlsSource = url.includes('.m3u8');
    let hls: Hls | null = null;

    const onReadyToSwitch = () => {
        playTick(); 
        setActivePlayerIndex(nextIndex);
        setIsPlaying(true);
        setLoading(false);
        setSignalStrength(4);
        if (autoPlay) nextVideo.play().catch(() => {});
        setTimeout(() => {
            if (currentVideo) {
                currentVideo.pause();
                currentVideo.removeAttribute('src');
                currentVideo.load(); 
            }
            if (hlsRefs.current[activePlayerIndex]) {
                hlsRefs.current[activePlayerIndex]?.destroy();
                hlsRefs.current[activePlayerIndex] = null;
            }
        }, 500); 
    };

    const onError = (e: any) => {
        if (activePlayerIndex !== nextIndex) setActivePlayerIndex(nextIndex);
        setError(isRadio ? "电台无法连接" : "直播流无法播放");
        setLoading(false);
        setSignalStrength(0);
    };

    nextVideo.addEventListener('error', onError);
    nextVideo.addEventListener('canplay', onReadyToSwitch);

    if (isHlsSource && Hls.isSupported()) {
      hls = new Hls({ enableWorker: true, lowLatencyMode: true, backBufferLength: 90 });
      hlsRefs.current[nextIndex] = hls;
      hls.loadSource(url);
      hls.attachMedia(nextVideo);
      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
          switch (data.type) {
            case Hls.ErrorTypes.NETWORK_ERROR: hls?.startLoad(); break;
            case Hls.ErrorTypes.MEDIA_ERROR: hls?.recoverMediaError(); break;
            default: onError(data); hls?.destroy(); break;
          }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.load();
    }

    return () => {
        nextVideo.removeEventListener('error', onError);
        nextVideo.removeEventListener('canplay', onReadyToSwitch);
    };
  }, [channel?.url, channel?.id]);

  const togglePlay = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;
    if (isPlaying) { video.pause(); setIsPlaying(false); }
    else { video.play(); setIsPlaying(true); }
  };

  const handleCast = async () => {
      const video = videoRefs[activePlayerIndex].current;
      if (video && 'remote' in video) {
          try {
              // @ts-ignore
              await video.remote.prompt();
              // @ts-ignore
              setIsCasting(video.remote.state !== 'disconnected');
          } catch (e) {
              console.error("Cast failed", e);
          }
      } else {
          alert("您的浏览器不支持投屏功能，请尝试使用 Chrome 或 Edge。");
      }
  };

  const handleStartRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;
    try {
        const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;
        if (!stream) { alert("您的浏览器不支持直接录制此媒体流。"); return; }
        const mimeType = MediaRecorder.isTypeSupported('video/webm; codecs=vp9') ? 'video/webm; codecs=vp9' : 'video/webm';
        const mediaRecorder = new MediaRecorder(stream, { mimeType });
        mediaRecorderRef.current = mediaRecorder;
        chunksRef.current = [];
        mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
        mediaRecorder.onstop = async () => {
            const blob = new Blob(chunksRef.current, { type: 'video/webm' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${channel?.name || 'recording'}.webm`;
            a.click();
            window.URL.revokeObjectURL(url);
            setIsRecording(false);
        };
        mediaRecorder.start();
        setIsRecording(true);
    } catch (e) {
        alert("无法录制。可能是由于版权保护或浏览器限制。");
    }
  };

  const handleStopRecording = () => {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
          mediaRecorderRef.current.stop();
      }
  };

  const handleSaveReminder = () => {
      if (!alarmTime || !channel) return;
      onAddReminder(channel, alarmTime);
      setShowAlarmPicker(false);
      setAlarmTime('');
  };

  if (!channel) {
    return (
      <div className={`w-full aspect-video flex flex-col items-center justify-center ${styles.card} ${styles.layoutShape} border-dashed opacity-70`}>
        {isRadio ? <Radio className={`w-16 h-16 mb-4 ${styles.textDim}`} /> : <TvIcon className={`w-16 h-16 mb-4 ${styles.textDim}`} />}
        <p className={styles.textDim}>请从列表中选择一个内容</p>
      </div>
    );
  }

  return (
    <div className={`w-full space-y-4 transition-all duration-300 ${isSticky ? 'fixed bottom-4 right-4 w-[320px] sm:w-[360px] z-[100]' : ''}`}>
      {isSticky && onCloseSticky && (
          <button onClick={(e) => { e.stopPropagation(); onCloseSticky(); }} className="absolute -top-3 -right-3 z-[110] bg-black text-white rounded-full p-1 shadow-lg hover:bg-red-500 transition-colors">
              <X className="w-4 h-4" />
          </button>
      )}
      <div className={`relative w-full aspect-video ${styles.layoutShape} overflow-hidden shadow-2xl group ${styles.border} ${theme.type === 'web95' ? 'bg-black' : styles.bgSidebar}`}>
        {theme.type === 'web95' && (
             <div className="absolute top-0 left-0 right-0 h-8 bg-[#000080] flex items-center justify-between px-2 z-20 select-none">
                 <span className="text-white font-bold text-xs">Media Player - {channel.name}</span>
             </div>
        )}
        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-500 ${isRadio ? 'opacity-0' : ''}`}
                style={{ opacity: activePlayerIndex === index && !isRadio ? 1 : 0, paddingTop: theme.type === 'web95' ? '32px' : '0', zIndex: activePlayerIndex === index ? 1 : 0 }}
            />
        ))}
        {isRadio && (
            <div className={`absolute inset-0 flex items-center justify-center pointer-events-none ${styles.bgSidebar} z-10`}>
                <div className={`w-32 h-32 rounded-full ${styles.card} flex items-center justify-center`}>
                    {channel.logo ? <img src={channel.logo} className="w-24 h-24 rounded-full object-cover" /> : <Music className={`w-12 h-12 ${styles.textMain}`} />}
                </div>
            </div>
        )}
        {loading && (
             <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/50 backdrop-blur-sm">
                <RefreshCw className={`w-8 h-8 ${styles.textMain} animate-spin`} />
             </div>
        )}
        {error && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/90 backdrop-blur-sm">
            <AlertCircle className="w-12 h-12 text-red-500 mb-3" />
            <p className="text-white font-medium">{error}</p>
          </div>
        )}
        <div className={`absolute inset-0 z-20 flex flex-col justify-between p-4 opacity-0 group-hover:opacity-100 bg-gradient-to-t from-black/80 via-transparent to-black/40 transition-opacity duration-300`}>
            <div className="flex justify-between items-start pointer-events-auto">
                 <div className="bg-red-600 px-2 py-1 rounded text-xs font-bold text-white">LIVE</div>
            </div>
            <div className="flex items-center gap-4 pointer-events-auto">
                <button onClick={togglePlay} className={`w-10 h-10 ${styles.layoutShape} flex items-center justify-center ${styles.buttonPrimary}`}>
                    {isPlaying ? <Square className="w-4 h-4 fill-current" /> : <Play className="w-4 h-4 fill-current" />}
                </button>
                <button onClick={() => setIsMuted(!isMuted)} className={`w-8 h-8 ${styles.layoutShape} flex items-center justify-center ${styles.button}`}>
                    {isMuted ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
                </button>
                <div className="flex-1"></div>
                <div className="flex items-center gap-2">
                    {canCast && (
                        <button onClick={handleCast} className={`p-2 ${styles.layoutShape} ${isCasting ? styles.buttonActive : styles.button}`} title="投屏"><Cast className="w-4 h-4" /></button>
                    )}
                    <button onClick={() => setShowAlarmPicker(!showAlarmPicker)} className={`p-2 ${styles.layoutShape} ${showAlarmPicker ? styles.buttonActive : styles.button}`} title="提醒"><AlarmClock className="w-4 h-4" /></button>
                    <button onClick={isRecording ? handleStopRecording : handleStartRecording} className={`p-2 ${styles.layoutShape} ${isRecording ? 'bg-red-500 text-white' : styles.button}`} title="录制"><StopCircle className="w-4 h-4" /></button>
                    <button onClick={() => { if (document.fullscreenElement) document.exitFullscreen(); else videoRefs[activePlayerIndex].current?.parentElement?.requestFullscreen(); }} className={`p-2 ${styles.layoutShape} ${styles.button}`}><Maximize className="w-4 h-4" /></button>
                </div>
            </div>
        </div>
      </div>
      {!isSticky && (
          <div className="flex items-start justify-between px-2">
            <div className="flex items-center gap-3 overflow-hidden">
                <div className={`w-10 h-10 ${styles.layoutShape} ${styles.bgSidebar} border ${styles.border} p-1.5 shrink-0`}>
                    {channel.logo ? <img src={channel.logo} className="w-full h-full object-contain" /> : <TvIcon className={`w-full h-full ${styles.textDim}`} />}
                </div>
                <div>
                    <h3 className={`font-bold text-lg ${styles.textMain} truncate`}>{channel.name}</h3>
                    <div className="flex items-center gap-1 text-xs font-mono opacity-80"><Clock className="w-3 h-3" /> {currentTimeStr}</div>
                </div>
            </div>
            <button onClick={onToggleFavorite} className={`p-2.5 ${styles.layoutShape} border ${isFavorite ? 'bg-yellow-500/10 border-yellow-500 text-yellow-500' : styles.button}`}><Star className={`w-5 h-5 ${isFavorite ? 'fill-current' : ''}`} /></button>
          </div>
      )}
    </div>
  );
};
const TvIcon = ({className}: {className?: string}) => (<svg className={className} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect width="20" height="15" x="2" y="7" rx="2" ry="2"/><polyline points="17 2 12 7 7 2"/></svg>);
